ON DUPLICATE KEY UPDATE order_code=order_code;

-- 订单评价数据（对应已完成订单）
-- 注意: evaluation 表使用 merchant_id, user_phone, score_quality, merchant_reply 等字段
ON DUPLICATE KEY UPDATE order_id=order_id;